"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5126],{5986:e=>{e.exports=JSON.parse('{"functions":[{"name":"EquipTypeOf","desc":"ItemConfig is a tagged union, so `config.EquipType` is only reachable on the\\narms that have it. Weapons always carry one; Ammo and Attachments never do.","params":[{"name":"config","desc":"","lua_type":"ItemConfig"}],"returns":[{"desc":"","lua_type":"string?\\n"}],"function_type":"method","source":{"line":146,"path":"src2/shared/EmberSharedLibrary/GameShared/Item2/ItemContext.luau"}},{"name":"IsEquippable","desc":"","params":[{"name":"config","desc":"","lua_type":"ItemConfig"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":157,"path":"src2/shared/EmberSharedLibrary/GameShared/Item2/ItemContext.luau"}},{"name":"IsConsumable","desc":"","params":[{"name":"config","desc":"","lua_type":"ItemConfig"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":172,"path":"src2/shared/EmberSharedLibrary/GameShared/Item2/ItemContext.luau"}},{"name":"Define","desc":"Builds a definition, filling the BaseContext defaults.\\n\\nNote `IsAvailable` defaults to FALSE, matching BaseContext:CheckAvailable,\\nwhich returned false so a context that forgot to implement it stayed hidden\\nrather than appearing and doing nothing.","params":[{"name":"name","desc":"","lua_type":"string"},{"name":"fields","desc":"","lua_type":"ContextFields"}],"returns":[{"desc":"","lua_type":"ContextDefinition\\n"}],"function_type":"method","source":{"line":186,"path":"src2/shared/EmberSharedLibrary/GameShared/Item2/ItemContext.luau"}}],"properties":[],"types":[],"name":"ItemContext","desc":"Item context actions -- Equip, Drop, Consume, Scrap, Use With.\\n\\nReplaces Item/Context/BaseContext.luau and the `:Extend()` chain under it.\\nA context is now a plain table of data plus function fields; there is no\\nprototype, no class, and nothing injected at load.\\n\\nWHAT CHANGES\\n\\n  * One typed request instead of five positional arguments. The old handlers\\n    took `(client, item_id, owned, context_item_id, metadata)` on the server\\n    and `(item_id, client, metadata)` on the client -- THE ORDER IS INVERTED\\n    between realms, which is a live footgun in a codebase where most contexts\\n    implement both. There is one `ContextRequest` record now.\\n\\n  * Handlers are grouped under `Client` and `Server` rather than spread across\\n    six similarly-named methods. Which realm a handler belongs to is a fact\\n    about the handler, so it belongs in the shape.\\n\\n  * `AppliesTo` (was `ContextFilter`) takes a CONFIG, not an item instance.\\n    It answers a question about the item KIND -- \\"can a backpack ever be\\n    scrapped\\" -- and the answer is the same for every instance, so it should\\n    not need one. This is what lets the context list be computed once per item\\n    kind at registration instead of per item.","source":{"line":30,"path":"src2/shared/EmberSharedLibrary/GameShared/Item2/ItemContext.luau"}}')}}]);